        dest_real = os.path.realpath(base_dir)
        member_path = os.path.join(base_dir, member.name)
        member_real = os.path.realpath(member_path)
        if not (member_real.startswith(dest_real + os.sep) or member_real == dest_real):
            raise RestoreError(f"archive entry {member.name} is outside the destination directory")

    with _open(archive_path) as tar:
        members = [m for m in tar.getmembers() if m.isfile() or m.isdir()]
        if len(members) > MAX_MEMBERS:
            raise RestoreError(f"backup has more than {MAX_MEMBERS} entries")
        if sum(m.size for m in members) > MAX_TOTAL_BYTES:
